/** Lossless ordered data for reviewed declarations. Rows and arrays are interned,
 * not removed: repeated roles and property order remain part of each snapshot.
 * Live controller hashes are read by the existing held-FD verifier above. */
type DeclarationValue = null | boolean | number | string |
  readonly DeclarationValue[] | { readonly [key: string]: DeclarationValue };
type DeclarationNode = readonly [0, null | boolean | number | string] |
  readonly [1, readonly number[]] | readonly [2, readonly (readonly [number, number])[]] |
  readonly [3, 0 | 1] | readonly [4] | readonly [5, 0 | 1];
function restoreDeclarations(nodes: readonly DeclarationNode[], root: number): DeclarationValue {
  const values: DeclarationValue[] = [];
  for (const node of nodes) {
    const read = (index: number): DeclarationValue => {
      if (!Number.isSafeInteger(index) || index < 0 || index >= values.length)
        throw new Error('Invalid reviewed declaration reference');
      return values[index]!;
    };
    switch (node[0]) {
      case 0: values.push(node[1]); break;
      case 1: values.push(Object.freeze(node[1].map(read))); break;
      case 2: values.push(Object.freeze(Object.fromEntries(node[1].map(([key, value]) => {
        const name = read(key);
        if (typeof name !== 'string') throw new Error('Invalid reviewed declaration key');
        return [name, read(value)] as const;
      })))); break;
      case 3: values.push(REVIEWED_CONTROLLER_POLICY_BINDINGS[node[1]]!.sha256); break;
      case 4: values.push(CONSUMER_SOURCE_BINDINGS); break;
      case 5: values.push(REVIEWED_CONTROLLER_POLICY_BINDINGS[node[1]]!); break;
    }
  }
  if (!Number.isSafeInteger(root) || root < 0 || root >= values.length)
    throw new Error('Invalid reviewed declaration root');
  return values[root]!;
}
